import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import type { Comment, Post } from '@/lib/types'

// Revalidate every 5 minutes
export const revalidate = 300

// Paths not returned by generateStaticParams are rendered on demand
// (replaces `fallback: 'blocking'`)
export const dynamicParams = true

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url, { next: { revalidate: 300 } })
  if (!res.ok) {
    throw new Error(`Failed to fetch ${url}: ${res.status}`)
  }
  return res.json()
}

// fetch requests are memoized, so generateMetadata and the page share results
async function getPostData(
  id: string
): Promise<{ post: Post; comments: Comment[] } | null> {
  try {
    const [post, comments] = await Promise.all([
      fetchJson<Post>(`https://jsonplaceholder.typicode.com/posts/${id}`),
      fetchJson<Comment[]>(
        `https://jsonplaceholder.typicode.com/posts/${id}/comments`
      ),
    ])
    return { post, comments }
  } catch {
    return null
  }
}

export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params
  const data = await getPostData(id)

  if (!data) {
    return {}
  }

  const description = data.post.body.substring(0, 160)

  return {
    title: `${data.post.title} - My Blog`,
    description,
    openGraph: {
      title: data.post.title,
      description,
    },
  }
}

export default async function BlogPost({ params }: PageProps<'/blog/[id]'>) {
  const { id } = await params
  const data = await getPostData(id)

  if (!data) {
    notFound()
  }

  const { post, comments } = data

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

