// Mirrors the Pages Router API body parser: an empty body parses to `{}`,
// and malformed JSON yields `null` so the caller can respond with a 400.
export async function parseJsonBody<T extends object>(
  request: Request
): Promise<Partial<T> | null> {
  const text = await request.text()
  if (text.length === 0) {
    return {}
  }

  try {
    const body: unknown = JSON.parse(text)
    return typeof body === 'object' && body !== null ? (body as Partial<T>) : {}
  } catch {
    return null
  }
}

